CREATE TABLE exception_rules(project_id uuid PRIMARY KEY REFERENCES projects(id),locked_days numeric(10,3) NOT NULL DEFAULT 30 CHECK(locked_days>0 AND locked_days<=3650),loaded_hours numeric(10,3) NOT NULL DEFAULT 48 CHECK(loaded_hours>0 AND loaded_hours<=87600),weight_tolerance numeric(14,6) NOT NULL DEFAULT 0 CHECK(weight_tolerance>=0),version int NOT NULL DEFAULT 1,updated_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE exception_rule_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),before_data jsonb,after_data jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE SEQUENCE exception_numbers;
CREATE TABLE inventory_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('EXC-'||lpad(nextval('exception_numbers')::text,8,'0')),project_id uuid NOT NULL REFERENCES projects(id),warehouse_id uuid REFERENCES warehouses(id),customer_id uuid REFERENCES customers(id),bundle_no text,category text NOT NULL CHECK(category IN('GAIN','LOSS','WEIGHT','LOCATION','LONG_LOCK','OVERDUE_LOAD','LEDGER')),source_key text NOT NULL,related_kind text NOT NULL,related_id uuid,description text NOT NULL,threshold_snapshot jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'NEW' CHECK(status IN('NEW','INVESTIGATING','PENDING','RESOLVED','CLOSED')),responsible_id uuid NOT NULL REFERENCES users(id),submitted_by uuid REFERENCES users(id),resolution text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),closed_at timestamptz,version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX one_open_exception ON inventory_exceptions(source_key) WHERE status<>'CLOSED';
CREATE TABLE exception_steps(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,exception_id uuid NOT NULL REFERENCES inventory_exceptions(id),action text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER exception_state BEFORE UPDATE OR DELETE ON inventory_exceptions FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE TRIGGER exception_rule_guard BEFORE UPDATE OR DELETE ON exception_rules FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE TRIGGER exception_rules_history BEFORE UPDATE OR DELETE ON exception_rule_history FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER exception_step_history BEFORE UPDATE OR DELETE ON exception_steps FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER temporal_document AFTER INSERT OR UPDATE ON inventory_exceptions FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE FUNCTION exception_configure(actor uuid,p uuid,expected int,config jsonb) RETURNS exception_rules LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE old exception_rules;d exception_rules;BEGIN
 PERFORM v24_revision();PERFORM v23_require(actor,'exception:configure',p,NULL,NULL);SELECT * INTO old FROM exception_rules WHERE project_id=p FOR UPDATE;IF coalesce(old.version,0)<>expected THEN RAISE EXCEPTION 'Rule version conflict' USING ERRCODE='23514';END IF;
 INSERT INTO exception_rules(project_id,locked_days,loaded_hours,weight_tolerance,updated_by) VALUES(p,(config->>'locked_days')::numeric,(config->>'loaded_hours')::numeric,(config->>'weight_tolerance')::numeric,actor) ON CONFLICT(project_id) DO UPDATE SET locked_days=excluded.locked_days,loaded_hours=excluded.loaded_hours,weight_tolerance=excluded.weight_tolerance,version=exception_rules.version+1,updated_by=actor,updated_at=v24_posting_time() RETURNING * INTO d;
 INSERT INTO exception_rule_history(project_id,before_data,after_data,actor_id) VALUES(p,to_jsonb(old),to_jsonb(d),actor);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,before_data,after_data) VALUES(actor,'exception_rules_updated','exception_rules',p::text,to_jsonb(old),to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION v24_raise_exception(actor uuid,p uuid,w uuid,c uuid,no text,category text,key text,kind text,related uuid,description text,thresholds jsonb DEFAULT '{}') RETURNS inventory_exceptions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d inventory_exceptions;BEGIN
 PERFORM v24_revision();PERFORM v23_require(actor,'exception:write',p,c,w);
 SELECT * INTO d FROM inventory_exceptions WHERE source_key=key AND status<>'CLOSED';IF FOUND THEN RETURN d;END IF;
 IF length(trim(description)) NOT BETWEEN 1 AND 2000 OR(w IS NOT NULL AND NOT EXISTS(SELECT 1 FROM warehouses WHERE id=w AND project_id=p)) OR(c IS NOT NULL AND NOT EXISTS(SELECT 1 FROM customers WHERE id=c AND project_id=p)) THEN RAISE EXCEPTION 'Exception data invalid' USING ERRCODE='23514';END IF;
 INSERT INTO inventory_exceptions(project_id,warehouse_id,customer_id,bundle_no,category,source_key,related_kind,related_id,description,threshold_snapshot,responsible_id,created_by) VALUES(p,w,c,no,category,key,kind,related,description,thresholds,actor,actor) RETURNING * INTO d;
 INSERT INTO exception_steps(exception_id,action,actor_id,note) VALUES(d.id,'DETECTED',actor,description);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'exception_detected','inventory_exceptions',d.id::text,to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION exception_manual(actor uuid,p uuid,w uuid,no text,cat text,description text) RETURNS inventory_exceptions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE customer uuid;BEGIN
 IF no IS NOT NULL THEN SELECT b.customer_id INTO customer FROM bundles b JOIN locations l ON l.id=b.location_id WHERE b.bundle_no=no AND b.project_id=p AND l.warehouse_id=w;END IF;
 RETURN v24_raise_exception(actor,p,w,customer,no,cat,'MANUAL-'||gen_random_uuid()::text,'MANUAL',NULL,description);END $$;
CREATE FUNCTION exception_action(actor uuid,doc uuid,expected int,action text,payload jsonb) RETURNS inventory_exceptions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d inventory_exceptions;note text;assignee uuid;BEGIN
 PERFORM v24_revision();SELECT * INTO d FROM inventory_exceptions WHERE id=doc FOR UPDATE;IF NOT FOUND OR d.version<>expected THEN RAISE EXCEPTION 'Exception version conflict' USING ERRCODE='23514';END IF;note:=trim(coalesce(payload->>'note',''));IF length(note) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Handling explanation required' USING ERRCODE='23514';END IF;
 PERFORM v23_require(actor,CASE WHEN action IN('resolve','close','reject') THEN 'exception:review' ELSE 'exception:write' END,d.project_id,d.customer_id,d.warehouse_id);
 IF action='investigate' AND d.status='NEW' THEN assignee:=coalesce((payload->>'responsible_id')::uuid,actor);PERFORM v23_require(assignee,'exception:write',d.project_id,d.customer_id,d.warehouse_id);UPDATE inventory_exceptions SET status='INVESTIGATING',responsible_id=assignee WHERE id=doc;
 ELSIF action='submit' AND d.status='INVESTIGATING' THEN UPDATE inventory_exceptions SET status='PENDING',submitted_by=actor,resolution=note WHERE id=doc;
 ELSIF action='resolve' AND d.status='PENDING' AND d.submitted_by<>actor THEN UPDATE inventory_exceptions SET status='RESOLVED',resolution=note WHERE id=doc;
 ELSIF action='reject' AND d.status='PENDING' AND d.submitted_by<>actor THEN UPDATE inventory_exceptions SET status='INVESTIGATING' WHERE id=doc;
 ELSIF action='close' AND d.status='RESOLVED' THEN UPDATE inventory_exceptions SET status='CLOSED',closed_at=v24_posting_time() WHERE id=doc;
 ELSE RAISE EXCEPTION 'Invalid transition or independent reviewer required' USING ERRCODE='23514';END IF;
 UPDATE inventory_exceptions SET version=version+1 WHERE id=doc RETURNING * INTO d;INSERT INTO exception_steps(exception_id,action,actor_id,note) VALUES(doc,action,actor,note);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'exception_'||action,'inventory_exceptions',doc::text,to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION exception_scan(actor uuid,p uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE rules jsonb;x record;n int:=0;d inventory_exceptions;BEGIN
 PERFORM v24_revision();PERFORM v23_require(actor,'exception:write',p,NULL,NULL);rules:=coalesce((SELECT to_jsonb(r) FROM exception_rules r WHERE project_id=p),jsonb_build_object('locked_days',30,'loaded_hours',48,'weight_tolerance',0,'version',0));
 FOR x IN SELECT b.bundle_no,b.customer_id,l.warehouse_id,r.id FROM reservations r JOIN bundles b ON b.id=r.bundle_id JOIN locations l ON l.id=b.location_id WHERE b.project_id=p AND b.physical_status='IN_STOCK' AND r.released_at IS NULL AND r.locked_at<v24_posting_time()-((rules->>'locked_days')::numeric*interval '1 day') LOOP d:=v24_raise_exception(actor,p,x.warehouse_id,x.customer_id,x.bundle_no,'LONG_LOCK','LOCK-'||x.id,'RESERVATION',x.id,'有效锁定超过管理员阈值',rules);n:=n+1;END LOOP;
 FOR x IN SELECT d.id,d.customer_id,min(l.warehouse_id::text)::uuid AS warehouse_id FROM loading_orders d JOIN loading_items i ON i.loading_id=d.id JOIN bundles b ON b.id=i.bundle_id JOIN locations l ON l.id=b.location_id WHERE d.project_id=p AND d.status='LOADED' AND d.completed_at<v24_posting_time()-((rules->>'loaded_hours')::numeric*interval '1 hour') GROUP BY d.id LOOP d:=v24_raise_exception(actor,p,x.warehouse_id,x.customer_id,NULL,'OVERDUE_LOAD','LOAD-'||x.id,'LOADING',x.id,'装车完成后超过离场时限',rules);n:=n+1;END LOOP;
 FOR x IN SELECT w.id,w.customer_id,min(l.warehouse_id::text)::uuid AS warehouse_id,w.difference FROM weighings w JOIN weighing_items i ON i.weighing_id=w.id JOIN bundles b ON b.id=i.bundle_id JOIN locations l ON l.id=b.location_id WHERE w.project_id=p AND w.status='RECORDED' AND abs(w.difference)>(rules->>'weight_tolerance')::numeric AND NOT EXISTS(SELECT 1 FROM outbound_orders o WHERE o.weighing_id=w.id AND o.variance_by IS NOT NULL AND o.status<>'CANCELLED') GROUP BY w.id LOOP d:=v24_raise_exception(actor,p,x.warehouse_id,x.customer_id,NULL,'WEIGHT','WEIGH-'||x.id,'WEIGHING',x.id,'检斤差异（吨）：'||x.difference::text,rules);n:=n+1;END LOOP;
 FOR x IN SELECT b.id,b.bundle_no,b.customer_id,l.warehouse_id FROM bundles b JOIN locations l ON l.id=b.location_id JOIN warehouses w ON w.id=l.warehouse_id WHERE b.project_id=p AND b.physical_status='IN_STOCK' AND(NOT l.active OR NOT w.active OR EXISTS(SELECT 1 FROM yards y WHERE y.id=l.yard_id AND NOT y.active)) LOOP d:=v24_raise_exception(actor,p,x.warehouse_id,x.customer_id,x.bundle_no,'LOCATION','LOC-'||x.id,'BUNDLE',x.id,'实物位于停用或异常位置',rules);n:=n+1;END LOOP;
 FOR x IN SELECT b.id,b.bundle_no,b.customer_id,l.warehouse_id,CASE WHEN b.physical_status='IN_STOCK' THEN b.net_weight ELSE 0 END AS current_qty,o.opening_qty+coalesce((SELECT sum(e.physical_delta) FROM inventory_events e WHERE e.bundle_id=b.id AND e.revision_id IS NOT NULL),0) AS ledger_qty FROM bundles b JOIN inventory_origins o ON o.bundle_id=b.id JOIN locations l ON l.id=b.location_id WHERE b.project_id=p LOOP IF x.current_qty<>x.ledger_qty THEN d:=v24_raise_exception(actor,p,x.warehouse_id,x.customer_id,x.bundle_no,'LEDGER','LEDGER-'||x.id,'BUNDLE',x.id,'期初+库存流水与当前实物不一致；账面='||x.ledger_qty::text||'，当前='||x.current_qty::text,rules);n:=n+1;END IF;END LOOP;
 RETURN jsonb_build_object('matched_conditions',n,'rules',rules);END $$;
CREATE FUNCTION v24_count_exceptions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE x jsonb;cat text;customer uuid;BEGIN IF NEW.status='APPROVED' AND OLD.status<>'APPROVED' THEN FOR x IN SELECT * FROM jsonb_array_elements(NEW.approved_report->'rows') LOOP
 cat:=x->>'finding';IF cat IN('GAIN','LOSS','WEIGHT','LOCATION') THEN SELECT customer_id INTO customer FROM bundles WHERE bundle_no=x->>'bundle_no' AND project_id=NEW.project_id;PERFORM v24_raise_exception(NEW.reviewed_by,NEW.project_id,NEW.warehouse_id,customer,x->>'bundle_no',cat,'COUNT-'||NEW.id::text||'-'||(x->>'bundle_no')||'-'||cat,'STOCKTAKE',NEW.id,'盘点批准差异：'||x::text);END IF;END LOOP;END IF;RETURN NEW;END $$;
CREATE TRIGGER count_exception_detection AFTER UPDATE ON stocktakes FOR EACH ROW EXECUTE FUNCTION v24_count_exceptions();
REVOKE ALL ON FUNCTION v24_raise_exception(uuid,uuid,uuid,uuid,text,text,text,text,uuid,text,jsonb),exception_configure(uuid,uuid,int,jsonb),exception_manual(uuid,uuid,uuid,text,text,text),exception_action(uuid,uuid,int,text,jsonb),exception_scan(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exception_configure(uuid,uuid,int,jsonb),exception_manual(uuid,uuid,uuid,text,text,text),exception_action(uuid,uuid,int,text,jsonb),exception_scan(uuid,uuid) TO musonoi_app;
GRANT SELECT ON exception_rules,exception_rule_history,inventory_exceptions,exception_steps TO musonoi_app;
